scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).isClientOnly()) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsGlideRecord(ast).nestedQueries();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-GR-004',
        title: 'Query inside a query loop',
        recommendation: 'Fetch the related records with one query before the loop (for example addQuery(field, \'IN\', ids) or addJoinQuery) and look them up in an object, or use GlideAggregate. Nested queries run once per outer row.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
